function UserStatus({ isLoggedIn, isAdmin, notifications }) {
  // Pattern 1: if/else before return
  if (!isLoggedIn) {
    return <p>Please log in.</p>;
  }

  return (
    <div>
      {/* Pattern 2: Ternary operator */}
      <p>{isAdmin ? 'Welcome, Admin!' : 'Welcome, User!'}</p>

      {/* Pattern 3: Logical && */}
      {notifications > 0 && (
        <span>You have {notifications} notifications</span>
      )}
    </div>
  );
}

function Alert({ type, message }) {
  const className = type === 'error'
    ? 'alert alert-error'
    : type === 'success'
    ? 'alert alert-success'
    : 'alert alert-info';

  return <div className={className}>{message}</div>;
}
